Object.assign(T, boardStrings);

const build = (idx) => {
  const out = {};
  for (const [key, tuple] of Object.entries(T)) {
    const parts = key.split('.');
    let o = out;
    parts.slice(0, -1).forEach((p) => { o = (o[p] ||= {}); });
    o[parts[parts.length - 1]] = tuple[idx];
  }
  return out;
};

export default { pt: build(0), en: build(1), es: build(2) };
